local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds
local UIModule = CS.Engine.UI.UIModule

---@class DamageRewardService
local DamageRewardService = Class("DamageRewardService")

function DamageRewardService.new(facade)
    local obj = DamageRewardService.New()
    obj.facade = facade
    obj.CoClick = nil
    return obj
end

function DamageRewardService:UpdateInfo()
    SetButtonAction(self.facade.BtnReward, Bind(self, self.OnClick))
end

function DamageRewardService:OnClick()
    if self.CoClick then
        cs_coroutine.stop(self.CoClick)
        self.CoClick = nil
    end
    self.CoClick = cs_coroutine.start(function()
        UIModule.OpenDialog({
            id = Constants.UITypeIds.UIWorldBossDamageBonusDialog
        })
    end)
end

function DamageRewardService:Dispose()
    if self.CoClick then
        cs_coroutine.stop(self.CoClick)
        self.CoClick = nil
    end
end

return DamageRewardService